import sys
from collections import deque

MAX_SIZE = 7100
INF = 1000000000

class MaxFlowSolver:
    class Edge:
        def __init__(self, from_, to, flow, capacity):
            self.from_ = from_
            self.to = to
            self.flow = flow
            self.capacity = capacity

    def __init__(self):
        self.edges = []
        self.adj = [[] for _ in range(MAX_SIZE)]
        self.s = 0
        self.t = MAX_SIZE - 2
        self.dist = [0] * MAX_SIZE
        self.visited = [0] * MAX_SIZE
        self.current = [0] * MAX_SIZE

    def reset(self):
        self.edges.clear()
        for i in range(MAX_SIZE):
            self.adj[i].clear()

    def addEdge(self, u, v, cap):
        e1 = self.Edge(u, v, 0, cap)
        e2 = self.Edge(v, u, 0, 0)
        self.edges.append(e1)
        self.edges.append(e2)
        self.adj[u].append(len(self.edges) - 2)
        self.adj[v].append(len(self.edges) - 1)

    def buildGraph(self):
        for i in range(MAX_SIZE):
            self.visited[i] = 0
            self.dist[i] = 0
        q = deque()
        q.append(self.s)
        self.visited[self.s] = 1
        self.dist[self.s] = 0
        while q:
            v = q.popleft()
            for i in self.adj[v]:
                e = self.edges[i]
                u = e.to
                if not self.visited[u] and e.capacity > e.flow:
                    self.dist[u] = self.dist[v] + 1
                    q.append(u)
                    self.visited[u] = 1
        return self.visited[self.t]

    def sendFlow(self, v, flow):
        if v == self.t or flow == 0:
            return flow
        total = 0
        for i in range(self.current[v], len(self.adj[v])):
            e = self.edges[self.adj[v][i]]
            if self.dist[v] + 1 == self.dist[e.to]:
                pushed = self.sendFlow(e.to, min(flow, e.capacity - e.flow))
                if pushed > 0:
                    e.flow += pushed
                    self.edges[self.adj[v][i] ^ 1].flow -= pushed
                    total += pushed
                    flow -= pushed
                    if flow == 0:
                        break
            self.current[v] += 1
        return total

    def maxFlow(self):
        totalFlow = 0
        while self.buildGraph():
            for i in range(MAX_SIZE):
                self.current[i] = 0
            totalFlow += self.sendFlow(self.s, INF)
        return totalFlow

def BFS(x, y, mazeA, visitedCells, distCells, sizeN):
    q = deque()
    for i in range(14):
        for j in range(14):
            distCells[i][j] = 111
    distCells[x][y] = 0
    q.append(((x, y), 0))
    dx = [1, 0, 0, -1]
    dy = [0, 1, -1, 0]
    while q:
        (cx, cy), d = q.popleft()
        if visitedCells[cx][cy]:
            continue
        visitedCells[cx][cy] = True
        distCells[cx][cy] = d
        for i in range(4):
            tx = cx + dx[i]
            ty = cy + dy[i]
            if tx <= 0 or tx > sizeN or ty <= 0 or ty > sizeN:
                continue
            if visitedCells[tx][ty] or mazeA[tx][ty] == 'Y':
                continue
            q.append(((tx, ty), d + 1))

def get_idx(level, x, y, sizeN):
    return level * sizeN * sizeN + (x - 1) * sizeN + y

def main():
    input = sys.stdin.read().split()
    sizeN = int(input[0])
    t = int(input[1])
    mazeA = [[''] * (sizeN + 1)]
    mazeB = [[''] * (sizeN + 1)]
    index = 2
    for _ in range(sizeN):
        row = [''] + list(input[index])
        mazeA.append(row)
        index += 1
    for _ in range(sizeN):
        row = [''] + list(input[index])
        mazeB.append(row)
        index += 1

    solver = MaxFlowSolver()
    solver.s = 0
    solver.t = MAX_SIZE - 2
    visitedCells = [[False] * 14 for _ in range(14)]
    distCells = [[111] * 14 for _ in range(14)]
    targetIdx = [0] * 103

    zx, zy = 0, 0
    for i in range(1, sizeN + 1):
        for j in range(1, sizeN + 1):
            if mazeA[i][j] == 'Z':
                zx, zy = i, j
                break

    for i in range(1, sizeN * sizeN + 1):
        targetIdx[i] = MAX_SIZE - 3 - (sizeN * sizeN - i)

    BFS(zx, zy, mazeA, visitedCells, distCells, sizeN)

    for i in range(1, sizeN + 1):
        for j in range(1, sizeN + 1):
            if mazeA[i][j] >= '0' and mazeA[i][j] <= '9':
                solver.addEdge(solver.s, get_idx(0, i, j, sizeN), ord(mazeA[i][j]) - ord('0'))
            if mazeB[i][j] >= '0' and mazeB[i][j] <= '9':
                solver.addEdge(targetIdx[get_idx(0, i, j, sizeN)], solver.t, ord(mazeB[i][j]) - ord('0'))
            solver.addEdge(get_idx(0, i, j, sizeN), targetIdx[get_idx(0, i, j, sizeN)], INF)

    dx = [1, 0, 0, -1]
    dy = [0, 1, -1, 0]
    for i in range(1, t + 1):
        for j in range(1, sizeN + 1):
            for k in range(1, sizeN + 1):
                if mazeA[j][k] == 'Y' or mazeA[j][k] == 'Z':
                    continue
                for l in range(4):
                    tx = j + dx[l]
                    ty = k + dy[l]
                    if 1 <= tx <= sizeN and 1 <= ty <= sizeN:
                        if mazeA[tx][ty] != 'Y' and mazeA[tx][ty] != 'Z':
                            if distCells[j][k] >= i and distCells[tx][ty] >= i:
                                solver.addEdge(get_idx(i - 1, tx, ty, sizeN), get_idx(i, j, k, sizeN), INF)
                solver.addEdge(get_idx(i, j, k, sizeN), targetIdx[get_idx(0, j, k, sizeN)], INF)

    print(solver.maxFlow())

if __name__ == "__main__":
    main()

